.darma-loader-darma-b16-mars-rover-tracks { --accent: var(--loader-color, #c2410c); --accent-2: var(--loader-secondary-color, #fed7aa); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .62); position: relative; overflow: hidden; }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__regolith { position: absolute; left: 0; right: 0; bottom: 12%; height: 5%; border-radius: 3px; background: color-mix(in srgb, var(--accent) 40%, transparent); }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__rover { position: absolute; left: 22%; bottom: 16%; width: 56%; height: 46%; animation: darma-loader-darma-b16-mars-rover-tracks-rover-jolt calc(var(--loader-speed, 1s) * .8) ease-in-out infinite; }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__deck { position: absolute; left: 4%; bottom: 26%; width: 92%; height: 34%; border-radius: 5px; background: linear-gradient(var(--accent-2), var(--accent)); }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__mast { position: absolute; left: 68%; bottom: 58%; width: 9%; height: 42%; border-radius: 3px; background: #94a3b8; }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__mast::after { content: ''; position: absolute; left: -40%; top: -8%; width: 180%; height: 26%; border-radius: 2px; background: var(--accent-2); }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__wheel { position: absolute; bottom: 0; width: 20%; height: 30%; border-radius: 50%; background: radial-gradient(circle, #475569 0 32%, #1e293b 34%); animation: darma-loader-darma-b16-mars-rover-tracks-rover-roll calc(var(--loader-speed, 1s) * .8) linear infinite; }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__wheel:nth-of-type(3) { left: 4%; }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__wheel:nth-of-type(4) { left: 40%; }
.darma-loader-darma-b16-mars-rover-tracks .darma-loader-darma-b16-mars-rover-tracks__wheel:nth-of-type(5) { left: 76%; }
.darma-loader-darma-b16-mars-rover-tracks i { position: absolute; bottom: 6%; width: 6%; height: 4%; border-radius: 2px; background: color-mix(in srgb, var(--accent) 55%, transparent); animation: darma-loader-darma-b16-mars-rover-tracks-rover-track calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b16-mars-rover-tracks i:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b16-mars-rover-tracks i:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
@keyframes darma-loader-darma-b16-mars-rover-tracks-rover-roll { to { transform: rotate(1turn); } }
@keyframes darma-loader-darma-b16-mars-rover-tracks-rover-jolt { 0%, 100% { transform: translateY(0) rotate(0deg); } 30% { transform: translateY(-3%) rotate(-1.5deg); } 70% { transform: translateY(-2%) rotate(1.5deg); } }
@keyframes darma-loader-darma-b16-mars-rover-tracks-rover-track { 0% { left: 24%; opacity: 0; } 12% { opacity: 1; } 100% { left: -8%; opacity: 0; } }

